<?php
$facultyRows = $pdo->query(
    'SELECT faculty.*, users.full_name, users.username FROM faculty
     JOIN users ON users.id = faculty.user_id ORDER BY users.full_name'
)->fetchAll();
?>
<section class="page-heading-row"><div><span class="eyebrow">MEET THE PEOPLE WHO TEACH</span><h1>Faculty<span class="heading-dot">.</span></h1><p>Faculty profiles and department information.</p></div><span class="count-chip"><?= count($facultyRows) ?> members</span></section>
<?php if ($role === 'admin'): ?><section class="panel form-panel"><div class="panel-heading"><div><span class="eyebrow">PEOPLE & PROFILES</span><h2>Add a faculty member</h2></div><span class="form-step">01 <i>/</i> profile</span></div>
<form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_faculty"><input type="hidden" name="return_to" value="faculty">
<label class="form-field"><span>Full name</span><input name="full_name" required maxlength="120" placeholder="e.g. Dr. Maya Patel"></label><label class="form-field"><span>Department</span><input name="department" required maxlength="100" placeholder="e.g. Computer Science"></label><label class="form-field"><span>Username</span><input name="username" required maxlength="80" placeholder="Choose a login name"></label><label class="form-field"><span>Temporary password</span><input name="password" type="password" minlength="8" required placeholder="At least 8 characters"></label><label class="form-field"><span>Designation</span><input name="designation" required maxlength="100" placeholder="e.g. Associate Professor"></label>
<div class="form-submit-row"><span>Use a temporary password and share it securely.</span><button class="button button-primary" type="submit">Add faculty <span>→</span></button></div></form></section><?php endif; ?>
<section class="faculty-grid"><?php foreach ($facultyRows as $index => $member): ?><article class="faculty-card"><div class="faculty-card-top"><span class="faculty-avatar faculty-avatar-<?= $index % 4 ?>"><?= e(strtoupper(substr($member['full_name'], 0, 1))) ?></span><span class="faculty-status"><i></i> Active</span></div><h3><?= e($member['full_name']) ?></h3><p><?= e($member['designation']) ?></p><div class="faculty-dept"><span>⌘</span><?= e($member['department']) ?></div><div class="faculty-card-foot"><span>@<?= e($member['username']) ?></span><span>Faculty member</span></div></article><?php endforeach; ?>
<?php if (!$facultyRows): ?><div class="panel empty-state"><span class="empty-art">✳</span><b>No faculty profiles yet</b><p>Faculty profiles will appear here once they are added.</p></div><?php endif; ?></section>
